mkitem!{mkstruct!{pub struct UnsafeListEntry < T > { next : NonNull < UnsafeListEntry < T > > , prev : NonNull < UnsafeListEntry < T > > , value : Option < T > , }}}
mkitem!{mkimpl!{impl < T > UnsafeListEntry < T > { fn dummy () -> Self { UnsafeListEntry { next : NonNull :: dangling () , prev : NonNull :: dangling () , value : None } } pub fn new (value : T) -> Self { UnsafeListEntry { value : Some (value) , .. Self :: dummy () } } }}}
mkitem!{mkstruct!{pub struct UnsafeList < T > { head_tail : NonNull < UnsafeListEntry < T > > , head_tail_entry : Option < UnsafeListEntry < T > > , }}}
mkitem!{mkimpl!{impl < T > UnsafeList < T > { pub const fn new () -> Self { unsafe { UnsafeList { head_tail : NonNull :: new_unchecked (1 as _) , head_tail_entry : None } } } # [doc = " # Safety"] unsafe fn init (& mut self) { if self . head_tail_entry . is_none () { self . head_tail_entry = Some (UnsafeListEntry :: dummy ()) ; self . head_tail = unsafe { NonNull :: new_unchecked (self . head_tail_entry . as_mut () . unwrap ()) } ; unsafe { self . head_tail . as_mut () } . next = self . head_tail ; unsafe { self . head_tail . as_mut () } . prev = self . head_tail ; } } pub fn is_empty (& self) -> bool { if self . head_tail_entry . is_some () { let first = unsafe { self . head_tail . as_ref () } . next ; if first == self . head_tail { unsafe { rtassert ! (self . head_tail . as_ref () . prev == first) } ; true } else { false } } else { true } } # [doc = " Pushes an entry onto the back of the list."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The entry must remain allocated until the entry is removed from the"] # [doc = " list AND the caller who popped is done using the entry. Special"] # [doc = " care must be taken in the caller of `push` to ensure unwinding does"] # [doc = " not destroy the stack frame containing the entry."] pub unsafe fn push < 'a > (& mut self , entry : & 'a mut UnsafeListEntry < T >) -> & 'a T { unsafe { self . init () } ; let mut entry = unsafe { NonNull :: new_unchecked (entry) } ; let mut prev_tail = mem :: replace (& mut unsafe { self . head_tail . as_mut () } . prev , entry) ; unsafe { entry . as_mut () } . prev = prev_tail ; unsafe { entry . as_mut () } . next = self . head_tail ; unsafe { prev_tail . as_mut () } . next = entry ; unsafe { (* entry . as_ptr ()) . value . as_ref () } . unwrap () } # [doc = " Pops an entry from the front of the list."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must make sure to synchronize ending the borrow of the"] # [doc = " return value and deallocation of the containing entry."] pub unsafe fn pop < 'a > (& mut self) -> Option < & 'a T > { unsafe { self . init () } ; if self . is_empty () { None } else { let mut first = unsafe { self . head_tail . as_mut () } . next ; let mut second = unsafe { first . as_mut () } . next ; unsafe { self . head_tail . as_mut () } . next = second ; unsafe { second . as_mut () } . prev = self . head_tail ; unsafe { first . as_mut () } . next = NonNull :: dangling () ; unsafe { first . as_mut () } . prev = NonNull :: dangling () ; Some (unsafe { (* first . as_ptr ()) . value . as_ref () } . unwrap ()) } } # [doc = " Removes an entry from the list."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The caller must ensure that `entry` has been pushed onto `self`"] # [doc = " prior to this call and has not moved since then."] pub unsafe fn remove (& mut self , entry : & mut UnsafeListEntry < T >) { rtassert ! (! self . is_empty ()) ; let mut prev = entry . prev ; let mut next = entry . next ; unsafe { prev . as_mut () } . next = next ; unsafe { next . as_mut () } . prev = prev ; entry . next = NonNull :: dangling () ; entry . prev = NonNull :: dangling () ; } }}}